From 4f1c5a7c8109bd57e47f23327743fd38ce849bf2 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:31:06 +0100
Subject: [PATCH] containmentlayoutmanager: animate widgets removed from their
 context menu

A widget removed from its context menu vanished at once, because only
the edit mode Remove button shrank it first. Now the layout shrinks any
widget the user removes before deleting its container, the same way.

BUG: 351579
---
 .../appletslayout.cpp                         | 26 +++++++++++++++++++
 1 file changed, 26 insertions(+)

diff --git a/components/containmentlayoutmanager/appletslayout.cpp b/components/containmentlayoutmanager/appletslayout.cpp
index a3cee50db3..59b7b62ca5 100644
--- a/components/containmentlayoutmanager/appletslayout.cpp
+++ b/components/containmentlayoutmanager/appletslayout.cpp
@@ -9,7 +9,9 @@
 #include "containmentlayoutmanager_debug.h"
 #include "gridlayoutmanager.h"

+#include <QEasingCurve>
 #include <QGuiApplication>
+#include <QPropertyAnimation>
 #include <QQmlContext>
 #include <QQmlEngine>
 #include <QStyleHints>
@@ -721,6 +723,30 @@ void AppletsLayout::appletRemoved(Plasma::Applet *applet)

     m_layoutManager->releaseSpace(container);
     m_containerForApplet.remove(applet);
+
+    // The user removed the applet (e.g. from its context menu): shrink it away like the edit mode remove button does
+    QQmlEngine *engine = qmlEngine(this);
+    QObject *units = engine ? engine->singletonInstance<QObject *>(QStringLiteral("org.kde.kirigami.platform"), QStringLiteral("Units")) : nullptr;
+    const int duration = units ? units->property("longDuration").toInt() : 0;
+    if (applet->destroyed() && appletItem && container->isVisible() && container->scale() > 0 && duration > 0) {
+        // The applet hid itself when it got destroyed, keep it visible while it shrinks
+        appletItem->setVisible(true);
+        auto animation = new QPropertyAnimation(container, "scale", container);
+        animation->setDuration(duration);
+        animation->setEndValue(0.0);
+        animation->setEasingCurve(QEasingCurve::InOutQuad);
+        connect(animation, &QAbstractAnimation::finished, container, [container, appletItem = QPointer(appletItem)]() {
+            // Undo may already have moved the applet into a new container
+            if (appletItem && appletItem->parentItem() == container) {
+                appletItem->setParentItem(nullptr);
+                appletItem->setVisible(!appletItem->applet()->destroyed());
+            }
+            container->deleteLater();
+        });
+        animation->start(QAbstractAnimation::DeleteWhenStopped);
+        return;
+    }
+
     if (appletItem) {
         appletItem->setParentItem(nullptr);
     }
